public interface IPaymentMethod
{
    bool ProcessPayment(decimal amount);
}

public interface IShippable
{
    decimal CalculateShipping();
}

public abstract class Product
{
    public int Id { get; set; }
    public string Name { get; set; }
    public decimal Price { get; set; }
    public abstract decimal CalculateTax();
}

public class PhysicalProduct : Product, IShippable
{
    public double Weight { get; set; }
    public override decimal CalculateTax() => Price * 0.08m;
    public decimal CalculateShipping() => (decimal)Weight * 2;
}

public class DigitalProduct : Product
{
    public string DownloadUrl { get; set; }
    public override decimal CalculateTax() => Price * 0.05m;
}
